250|/**
251| * Chunking para documentos con estructura de secciones (markdown con headers)
252| * @param {string} content - Contenido markdown
253| * @param {Object} options - Opciones
254| * @returns {Array<Object>} Chunks preservando jerarquía
255| */
256|function chunkMarkdownDocument(content, options = {}) {
257|  const opts = { ...DEFAULT_OPTIONS, ...options };
258|
259|  // Dividir por headers (# ## ###)
260|  const sectionRegex = /^(#{1,6})\s+(.+)$/gm;
261|  const sections = [];
262|  let lastIndex = 0;
263|  let match;
264|
265|  while ((match = sectionRegex.exec(content)) !== null) {
266|    const headerLevel = match[1].length;
267|    const headerText = match[2];
268|    const startIndex = match.index;
269|
270|    if (startIndex > lastIndex) {
271|      // Contenido antes de este header
272|      const prevContent = content.slice(lastIndex, startIndex).trim();
273|      if (prevContent) {
274|        sections.push({ level: 0, title: '', content: prevContent });
275|      }
276|    }
277|
278|    sections.push({ level: headerLevel, title: headerText, content: '' });
279|    lastIndex = sectionRegex.lastIndex;
280|  }
281|
282|  // Capturar contenido después del último header
283|  if (lastIndex < content.length) {
284|    const remaining = content.slice(lastIndex).trim();
285|    if (remaining) {
286|      sections.push({ level: 0, title: '', content: remaining });
287|    }
288|  }
289|
290|  // Procesar cada sección
291|  const allChunks = [];
292|  let globalIndex = 0;
293|
294|  for (const section of sections) {
295|    if (!section.content.trim()) continue;
296|
297|    const sectionChunks = chunkDocument(section.content, options);
298|
299|    for (const chunk of sectionChunks) {
300|      allChunks.push({
301|        ...chunk,
302|        index: globalIndex++,
303|        sectionTitle: section.title,
304|        sectionLevel: section.level,
305|      });
306|    }
307|  }
308|
309|  // Actualizar totalChunks e índices
310|  return allChunks.map((chunk, i) => ({
311|    ...chunk,
312|    index: i,
313|    totalChunks: allChunks.length,
314|  }));
