{"content": "1|/**
2| * Servicio RAG (Retrieval-Augmented Generation)
3| * Busca conocimiento técnico de belleza en la base de datos pgvector
4| */
5|
6|require('dotenv').config();
7|const { ragPool } = require('../config/db');
8|const axios = require('axios');
9|
10|const NVIDIA_API_KEY = process.env.NVIDIA_API_KEY;
11|const NVIDIA_API_URL = process.env.NVIDIA_API_URL || 'https://integrate.api.nvidia.com/v1/embeddings';
12|const NVIDIA_EMBEDDING_MODEL = process.env.NVIDIA_EMBEDDING_MODEL || 'nvidia/nv-embedqa-e5-v5';
13|const EXPECTED_DIMS = 1024;
14|
15|// ─── Generar embedding de un texto ───────────────────────────────────
16|async function generateEmbedding(text) {
17|  if (!NVIDIA_API_KEY) throw new Error('NVIDIA_API_KEY no configurada');
18|
19|  const response = await axios.post(
20|    NVIDIA_API_URL,
21|    {
22|      model: NVIDIA_EMBEDDING_MODEL,
23|      input: [text],
24|      input_type: 'query',
25|      encoding_format: 'float',
26|    },
27|    {
28|      headers: {
29|        'Authorization': `Bearer ${NVIDIA_API_KEY}`,
30|        'Content-Type': 'application/json',
31|      },
32|      timeout: 15000,
33|    }
34|  );
35|
36|  const embedding = response.data?.data?.[0]?.embedding;
37|  if (!embedding || embedding.length !== EXPECTED_DIMS) {
38|    throw new Error(`Embedding inválido: ${embedding ? embedding.length : 0} dims`);
39|  }
40|  return embedding;
41|}
42|
43|// ─── Construir filtros de metadata ───────────────────────────────────
44|// FIX BUG #5: acepta startIndex para no chocar con $1 del vector
45|function buildMetadataFilters(filters = {}, startIndex = 1) {
46|  const conditions = [];
47|  const params = [];
48|  let paramIndex = startIndex;
49|
50|  if (filters.skin_type && filters.skin_type !== 'all') {
51|    conditions.push(`skin_type ILIKE $${paramIndex}`);
52|    params.push(`%${filters.skin_type}%`);
53|    paramIndex++;
54|  }
55|
56|  if (filters.category) {
57|    conditions.push(`category = $${paramIndex}`);
58|    params.push(filters.category);
59|    paramIndex++;
60|  }
61|
62|  if (filters.contraindications && Array.isArray(filters.contraindications)) {
63|    filters.contraindications.forEach(c => {
64|      conditions.push(`contraindications::text ILIKE $${paramIndex}`);
65|      params.push(`%${c}%`);
66|      paramIndex++;
67|    });
68|  }
69|
70|  if (filters.ingredients && Array.isArray(filters.ingredients)) {
71|    filters.ingredients.forEach(i => {
72|      conditions.push(`ingredients::text ILIKE $${paramIndex}`);
73|      params.push(`%${i}%`);
74|      paramIndex++;
75|    });
76|  }
77|
78|  const whereClause = conditions.length > 0
79|    ? `WHERE ${conditions.join(' AND ')}`
80|    : '';
81|
82|  return { whereClause, params };
83|}
84|
85|// ─── Búsqueda vectorial principal ────────────────────────────────────
86|async function searchBeautyKnowledge(query, options = {}) {
87|  const { topK = 5, threshold = 0.45, filters = {} } = options;
88|
89|  try {
90|    // Generar embedding del query
91|    const queryEmbedding = await generateEmbedding(query);
92|    const embeddingStr = `[${queryEmbedding.join(',')}]`;
93|
94|    // FIX BUG #5: startIndex=2 porque $1 es el vector de búsqueda
95|    const { whereClause, params: filterParams } = buildMetadataFilters(filters, 2);
96|
97|    // FIX BUG #3: usar filterParams.length (no params)
98|    const sql = `
99|      SELECT
100|        id,
101|        title,
102|        content,
103|        category,
104|        1 - (embedding <=> $1::vector) AS similarity
105|      FROM beauty_knowledge_embeddings
106|      ${whereClause}
107|      ${whereClause ? 'AND' : 'WHERE'} 1 - (embedding <=> $1::vector) >= $${filterParams.length + 2}
108|      ORDER BY embedding <=> $1::vector
109|      LIMIT $${filterParams.length + 3};
110|    `;
111|
112|    const queryParams = [embeddingStr, ...filterParams, threshold, topK];
113|    const result = await ragPool.query(sql, queryParams);
114|
115|    return result.rows.map(r => ({
116|      ...r,
117|      similarity: parseFloat(r.similarity),
118|    }));
119|
120|  } catch (error) {
121|    console.error('❌ Error en searchBeautyKnowledge:', error.message);
122|
123|    // FIX BUG #4: fallback full-text con manejo correcto de WHERE/AND
124|    try {
125|      console.warn('⚠️ RAG Vectorial falló. Usando fallback full-text...');
126|      const { whereClause, params: filterParams } = buildMetadataFilters(filters, 2);
127|      const textCondition = `(to_tsvector('spanish', title || ' ' || content) @@ plainto_tsquery('spanish', $1) OR title ILIKE $2 OR content ILIKE $2)`;
128|
129|      const combinedWhere = whereClause
130|        ? `${whereClause} AND ${textCondition}`
131|        : `WHERE ${textCondition}`;
132|
133|      const fallbackSql = `
134|        SELECT
135|          id,
136|          title,
137|          content,
138|          category,
139|          0.5 AS similarity
140|        FROM beauty_knowledge_embeddings
141|        ${combinedWhere}
142|        LIMIT $${filterParams.length + 3};
143|      `;
144|
145|      const fallbackParams = [query, `%${query}%`, ...filterParams, topK];
146|      const fallbackResult = await ragPool.query(fallbackSql, fallbackParams);
147|
148|      return fallbackResult.rows;
149|
150|    } catch (fallbackError) {
151|      console.error('❌ Fallback full-text también falló:', fallbackError.message);
152|      return [];
153|    }
154|  }
155|}
156|
157|// ─── Formatear chunks para inyección en prompt ───────────────────────
158|function formatKnowledgeContext(chunks) {
159|  if (!chunks || chunks.length === 0) return '';
160|
161|  return chunks.map((chunk, idx) => {
162|    const source = chunk.sources || chunk.metadata?.sources;
163|    const sourceText = source
164|      ? `\n   📚 Fuente: ${typeof source === 'string' ? source : JSON.stringify(source)}`
165|      : '';
166|    return `[${idx + 1}] ${chunk.title} (similitud: ${chunk.similarity?.toFixed(2) || 'N/A'})
167|${chunk.content}${sourceText}`;
168|  }).join('\n\n');
169|}
170|
171|module.exports = {
172|  searchBeautyKnowledge,
173|  formatKnowledgeContext,
174|  generateEmbedding,
175|};
