// LEGACY WRAPPER — Delegates to canonical ragService
// Does NOT execute retrieval; does NOT use dummy embeddings; does NOT reference aura_knowledge_chunks

require('dotenv').config();
const ragService = require('./ragService');

// Compat flag — si está false, el wrapper devuelve vacío (no rompe llamadas existentes)
const ENABLE_BEAUTY_RAG = process.env.ENABLE_BEAUTY_RAG === 'true';

/**
 * Busca chunks de conocimiento de belleza relevantes
 * DELEGA a ragService.searchBeautyKnowledge (canonical path)
 * @param {string} query - Consulta del usuario
 * @param {number} topK - Número de resultados (default: 3 para compatibilidad)
 * @param {number} threshold - Umbral de similitud (default: 0.7 para compatibilidad, ragService usa 0.45)
 * @returns {Promise<Array>} Chunks encontrados
 */
async function searchBeautyKnowledge(query, topK = 3, threshold = 0.7) {
  if (!ENABLE_BEAUTY_RAG) {
    return [];
  }

  try {
    // Delegar a ragService canónico
    // Mapear parámetros legacy -> canónicos
    const results = await ragService.searchBeautyKnowledge(query, {
      topK,
      threshold,
      filters: {}, // Legacy no pasaba filtros
    });

    // Transformar a formato legacy esperado por callers existentes
    return results.map(row => ({
      content: row.content,
      sourceType: row.metadata?.sourceType || row.category || 'beauty_knowledge',
      sourceId: row.id,
      title: row.title,
      metadata: row.metadata || {},
      similarity: row.similarity,
    }));

  } catch (error) {
    console.error('❌ [Legacy Wrapper] Error en searchBeautyKnowledge:', error.message);
    return [];
  }
}

/**
 * Formatea chunks para inyección en system prompt
 * DELEGA a ragService.formatKnowledgeContext
 * @param {Array} chunks - Chunks ya formateados por searchBeautyKnowledge
 * @returns {string} Contexto formateado
 */
function formatKnowledgeContext(chunks) {
  if (!chunks || chunks.length === 0) return '';

  // Usar el formateador canónico
  return ragService.formatKnowledgeContext(chunks);
}

module.exports = {
  searchBeautyKnowledge,
  formatKnowledgeContext,
  ENABLE_BEAUTY_RAG,
};", "path": "/c/beauty-app/backend/src/services/beautyKnowledgeService.js"}

