190|  const normalizedContent = content.replace(/\s+/g, ' ').trim();
191|
192|  if (!normalizedContent) {
193|    return [];
194|  }
195|
196|  // Estrategia: dividir por párrafos primero
197|  const paragraphs = splitIntoParagraphs(normalizedContent);
198|
199|  let allChunks = [];
200|
201|  if (opts.respectParagraphs) {
202|    // Procesar cada párrafo
203|    for (const paragraph of paragraphs) {
204|      const paraTokens = estimateTokens(paragraph);
