211|        const sentences = splitIntoSentences(paragraph);
212|        const sentenceChunks = combineIntoChunks(sentences, opts);
213|        allChunks.push(...sentenceChunks);
214|      }
215|    }
216|  } else {
217|    // Dividir todo por oraciones directamente
218|    const allSentences = paragraphs.flatMap(p => splitIntoSentences(p));
219|    allChunks = combineIntoChunks(allSentences, opts);
220|  }
221|
